fn game(sim:&Sim)->&Merc{sim.state.play.as_ref().unwrap().get::<Merc>().unwrap()}
fn game_mut(sim:&mut Sim)->&mut Merc{sim.state.play.as_mut().unwrap().get_mut::<Merc>().unwrap()}
