 let g=game(&self.sim);let mut frame=InputFrame::default();if cfg!(target_arch="wasm32"){frame.held=input["held"].as_u64().unwrap_or(0) as u32;frame.pressed=input["pressed"].as_u64().unwrap_or(0) as u32;let vec=|k:&str|Vec2::new(input[k][0].as_f64().unwrap_or(0.) as f32,input[k][1].as_f64().unwrap_or(0.) as f32);let mv=vec("move");frame.move_dir=Vec2::new(g.yaw.cos()*mv.x+g.yaw.sin()*mv.y,g.yaw.sin()*mv.x-g.yaw.cos()*mv.y);if g.riding.is_some(){frame.move_dir=Vec2::new(mv.x,0.);frame.axes=Vec2::new(input["throttle"].as_f64().unwrap_or(mv.y.max(0.) as f64) as f32,input["brake"].as_f64().unwrap_or((-mv.y).max(0.) as f64) as f32);}let mouse=vec("look");let stick=vec("stick");frame.look=mouse*g.settings.mouse.to_radians()+stick*g.settings.stick.to_radians()*elapsed as f32;if g.settings.invert{frame.look.y*=-1.;}frame.act=input["act"].as_u64().unwrap_or(0) as u32;}else{let k=|key|self.native.keys.contains(&key) as i32 as f32;let mv=Vec2::new(k(KeyCode::KeyD)-k(KeyCode::KeyA),k(KeyCode::KeyW)-k(KeyCode::KeyS)).clamp_length_max(1.);frame.move_dir=Vec2::new(g.yaw.cos()*mv.x+g.yaw.sin()*mv.y,g.yaw.sin()*mv.x-g.yaw.cos()*mv.y);frame.held=self.native.held;frame.pressed=std::mem::take(&mut self.native.pressed);frame.look=std::mem::take(&mut self.native.look)*g.settings.mouse.to_radians();frame.act=self.native.acts.pop_front().unwrap_or(0);}
 if self.ui_action!=0{frame.act=std::mem::take(&mut self.ui_action);}if let Some(h)=self.ui_hover.take(){game_mut(&mut self.sim).focus=h;}
 if self.test {if let Some(commands)=input["test"].as_array(){for c in commands{self.test_command(c);}}}
 let steps=((self.accum*60.).floor() as usize).min(180);if steps==0{return;}for n in 0..steps{let mut i=frame;if n>0{i.pressed=0;i.look=Vec2::ZERO;i.act=0;}if self.bot{i=self.sim.bot_input();}if self.server{i=InputFrame::default();}self.sim.step(&i);self.accum=(self.accum-1./60.).max(0.);}
 let mut play=self.sim.state.play.take().unwrap();let g=play.get_mut::<Merc>().unwrap();
 if let Some(d)=input["device"].as_u64(){g.device=d as u8;}if input["keyboard"].as_bool().unwrap_or(false){g.touch_only=false;}
 if g.load_slot>=0&&!g.session {let slot=g.load_slot;g.load_slot=-1;#[cfg(target_arch="wasm32")]let text=bridge_load(slot);#[cfg(not(target_arch="wasm32"))]let text=std::fs::read_to_string(format!("../notes/save-{slot}.json")).unwrap_or_default();match serde_json::from_str::<Merc>(&text){Ok(mut loaded)=>{loaded.screen="playing".into();loaded.streamed=None;loaded.load_slot=-1;loaded.save_slot=-1;loaded.pos.y=pav_core::games::merc::terrain::height(&loaded.data,loaded.pos.x,loaded.pos.z)+0.1;for n in &mut loaded.soldiers{n.entity=None;}for n in &g.soldiers{if let Some(id)=n.entity{self.sim.despawn(id);}}*g=loaded;g.sync_player(&mut self.sim);},Err(_)=>g.note(g.s("no_save").to_string())}}
 if g.save_serial!=self.saved_serial&&!g.session&&!g.attracting{self.saved_serial=g.save_serial;let text=serde_json::to_string(g).unwrap_or_default();#[cfg(target_arch="wasm32")] {bridge_save(0,&text);if g.save_slot>0{bridge_save(g.save_slot,&text);}}#[cfg(not(target_arch="wasm32"))]{let _=std::fs::write("../notes/save-0.json",&text);if g.save_slot>0{let _=std::fs::write(format!("../notes/save-{}.json",g.save_slot),&text);}}g.save_slot=-1;}
 if !self.server{if input["gesture"].as_bool().unwrap_or(false)&&self.audio.is_none(){self.audio=pav_audio::AudioOut::start().ok();}if let Some(audio)=&self.audio{audio.resume();audio.set_master(if self.ended{0.}else{g.settings.master});for c in self.score.update(g,elapsed as f32){audio.play_patch(c.patch,c.pan,c.gain*pav_audio::merc::gain(g,c.bus),c.delay);}}}
 #[cfg(target_arch="wasm32")] {if g.net_ui>0{bridge_network_ui(g.net_ui);g.net_ui=0;}if g.session&&g.round_started&&!self.ended&&!g.finished{self.network_at+=elapsed;self.delta_at+=elapsed;if self.network_at>=0.1{self.network_at=0.;let packet=if g.host{g.snapshot_packet(self.sim.state.tick)}else{g.pose_packet()};bridge_send(&serde_json::to_string(&packet).unwrap(),!g.host,-1);}if g.host&&self.delta_at>=0.2{self.delta_at=0.;let packet=g.delta_packet(self.delta_part);self.delta_part=(self.delta_part+1)%(g.fire.cells.len().div_ceil(350).max(1));bridge_send(&serde_json::to_string(&packet).unwrap(),true,-1);}}if g.finished&&g.host&&!self.finish_sent{self.finish_sent=true;bridge_finish(&serde_json::json!({"won":g.won,"score":g.team_score,"kills":g.kills,"cells":g.fire.total,"jams":g.coverage.contains("jam_cleared") as i32,"rescues":g.coverage.contains("player_rescued") as i32}).to_string());}}
 self.sim.state.play=Some(play);#[cfg(target_arch="wasm32")] {let g=game(&self.sim);let status=g.status(&self.sim);bridge_publish(&serde_json::json!({"status":status.to_string(),"ui":serde_json::json!({"screen":g.screen,"rows":g.rows(),"rects":self.rects,"focus":g.focus,"page":g.page,"device":g.device,"xbox":g.settings.xbox,"drawn":self.drawn}).to_string(),"screen":g.screen,"map":g.map_up,"voiceSerial":g.voice_serial,"subtitle":g.subtitle,"soundSerial":g.sound_serial,"touch":g.touch_only,"attract":g.attracting,"prompt":g.prompt().is_some()}).to_string());}
