 fn events(&mut self,input:&serde_json::Value){if let Some(es)=input["events"].as_array(){for e in es{let kind=e["kind"].as_str().unwrap_or("");if kind=="message"{if let Ok(packet)=serde_json::from_value::<Packet>(e["data"].clone()){let mut p=self.sim.state.play.take().unwrap();let g=p.get_mut::<Merc>().unwrap();g.receive(&mut self.sim,e["from"].as_u64().unwrap_or(0) as u8,packet,&mut Vec::new());self.sim.state.play=Some(p);}}else{let g=game_mut(&mut self.sim);match kind{"start"=>{g.round_started=true;g.screen="playing".into();g.round_time=0.;},"leave"=>g.leave(e["id"].as_u64().unwrap_or(0) as u8),"time-up"=>{g.finished=true;g.won=false;},"end"=>{self.ended=true;g.finished=true;if let Some(a)=&self.audio{a.set_master(0.);}},"standalone"=>{g.session=true;g.host=e["host"].as_bool().unwrap_or(false);g.local_id=e["id"].as_u64().unwrap_or(0) as u8;g.screen="card".into();g.pos=g.data.place("depot").pos()+Vec3::new(-65.+g.local_id as f32*2.,0.,70.);g.pos.y=pav_core::games::merc::terrain::height(&g.data,g.pos.x,g.pos.z);},_=>{}}}}}}
