pub fn run(settings:Settings)->Result<()>{let driver=Rc::new(RefCell::new(Driver::new(&settings)?));#[cfg(target_arch="wasm32")] {let d=driver.clone();let tick=Closure::<dyn FnMut()>::new(move||{if let Ok(mut d)=d.try_borrow_mut(){d.tick();}});let w=web_sys::window().unwrap();let _=js_sys::Reflect::set(&w,&JsValue::from_str("mercPump"),tick.as_ref());tick.forget();if driver.borrow().server{return Ok(());}}
 let event_loop=EventLoop::new()?;event_loop.set_control_flow(ControlFlow::Poll);let app=MercApp{driver,gfx:None,pending:None,ctx:egui::Context::default(),ui:None,builder:ViewBuilder::new(),started:false};#[cfg(target_arch="wasm32")] {use winit::platform::web::EventLoopExtWebSys;event_loop.spawn_app(app);}#[cfg(not(target_arch="wasm32"))]{let mut app=app;event_loop.run_app(&mut app)?;}Ok(())}
struct MercApp{driver:Rc<RefCell<Driver>>,gfx:Option<Gfx>,pending:Option<Rc<RefCell<Option<Result<Gfx>>>>>,ctx:egui::Context,ui:Option<UiInput>,builder:ViewBuilder,started:bool}
impl MercApp{
 fn finish_init(&mut self,gfx:Gfx){pav_ui::tenfoot::fonts(&self.ctx);self.ui=Some(UiInput::new(&self.ctx,&gfx.window,gfx.device.limits().max_texture_dimension_2d as usize));self.gfx=Some(gfx);}
 fn draw(&mut self){let Some(gfx)=&mut self.gfx else{return;};let mut d=self.driver.borrow_mut();d.tick();let mut frame=d.sim.frame();let (w,h)=gfx.size();if w==0||h==0{return;}let g=game(&d.sim).clone();let mut scene=if d.nodraw{pav_render::Scene::default()}else{self.builder.build(&frame,&frame,1.,&CameraRig::default(),w as f32/h as f32,&ViewSettings::default(),frame.focus)};
 if d.nodraw{scene.post.bloom=0.;scene.post.outlines=false;}let scale=(h as f32/1080.).max(0.25);self.ctx.set_zoom_factor(1.);let raw=self.ui.as_mut().unwrap().take(&gfx.window);let mut action=0;let mut hover=None;let mut rects=Vec::new();let output=self.ctx.run_ui(raw,|ui|{let r=pav_ui::tenfoot::draw(ui,&g);action=r.action;hover=r.hover;rects=r.rows;});let _=scale;d.ui_action=if action!=0{action}else{d.ui_action};d.ui_hover=hover;d.rects=rects;let ppp=output.pixels_per_point;let prims=self.ctx.tessellate(output.shapes,ppp);let mut textures=output.textures_delta;self.ui.as_mut().unwrap().platform_output(&gfx.window,output.platform_output);if gfx.draw(&scene,Some((&prims,&mut textures,ppp))){d.drawn+=1;}let _=&mut frame;
 }
}
impl ApplicationHandler for MercApp{
 fn resumed(&mut self,el:&ActiveEventLoop){if self.started{return;}self.started=true;let mut attrs=Window::default_attributes().with_title(pav_core::games::merc::data::data().s("title")).with_inner_size(winit::dpi::LogicalSize::new(1600.,900.));#[cfg(target_arch="wasm32")] {use winit::platform::web::WindowAttributesExtWebSys;attrs=attrs.with_append(true);}let window=match el.create_window(attrs){Ok(w)=>Arc::new(w),Err(e)=>{log::error!("window: {e}");return;}};
 #[cfg(not(target_arch="wasm32"))]match Gfx::new(window,pav_render::gpu::BackendChoice::Vulkan,true){Ok(g)=>self.finish_init(g),Err(e)=>log::error!("graphics: {e}")}
 #[cfg(target_arch="wasm32")] {let slot=Rc::new(RefCell::new(None));let fill=slot.clone();wasm_bindgen_futures::spawn_local(async move{*fill.borrow_mut()=Some(Gfx::create(window,pav_render::gpu::BackendChoice::Vulkan,true).await);});self.pending=Some(slot);}}
 fn about_to_wait(&mut self,_el:&ActiveEventLoop){let ready=self.pending.as_ref().and_then(|p|p.borrow_mut().take());if let Some(result)=ready {match result{Ok(g)=>self.finish_init(g),Err(e)=>{#[cfg(target_arch="wasm32")]bridge_failed(&format!("WebGPU could not start: {e}"));log::error!("{e}");}}self.pending=None;}self.driver.borrow_mut().tick();if let Some(g)=&self.gfx{g.window.request_redraw();}}
 fn window_event(&mut self,el:&ActiveEventLoop,_id:WindowId,event:WindowEvent){if let (Some(ui),Some(g))=(&mut self.ui,&self.gfx){ui.on_window_event(&g.window,&event);}match &event{WindowEvent::CloseRequested=>el.exit(),WindowEvent::Resized(s)=>{if let Some(g)=&mut self.gfx{g.resize(s.width,s.height);}},WindowEvent::RedrawRequested=>self.draw(),_=>{}}
 #[cfg(not(target_arch="wasm32"))] {let mut d=self.driver.borrow_mut();let shell=game(&d.sim).screen!="playing";match &event{WindowEvent::KeyboardInput{event,..}=>{if let PhysicalKey::Code(k)=event.physical_key{let pressed=event.state==ElementState::Pressed;if pressed{d.native.keys.insert(k);}else{d.native.keys.remove(&k);}if pressed&&!event.repeat{let a=key_action(k,shell);if a>0{d.native.acts.push_back(a);}}let bit=key_bit(k);if pressed{d.native.held|=bit;d.native.pressed|=bit;}else{d.native.held&=!bit;}}},WindowEvent::MouseInput{state,button,..}=>{let bit=if *button==MouseButton::Left{b::PRIMARY}else if *button==MouseButton::Right{b::SECONDARY}else{0};if state.is_pressed(){d.native.held|=bit;d.native.pressed|=bit;}else{d.native.held&=!bit;}},_=>{}}}}
 fn device_event(&mut self,_el:&ActiveEventLoop,_id:winit::event::DeviceId,event:DeviceEvent){if let DeviceEvent::MouseMotion{delta}=event{#[cfg(not(target_arch="wasm32"))]{self.driver.borrow_mut().native.look+=Vec2::new(delta.0 as f32,delta.1 as f32);}let _=delta;}}
}
#[cfg(not(target_arch="wasm32"))]fn key_bit(k:KeyCode)->u32{match k{KeyCode::ShiftLeft=>b::SPRINT,KeyCode::Space=>b::JUMP,_=>0}}
#[cfg(not(target_arch="wasm32"))]fn key_action(k:KeyCode,shell:bool)->u32{if k==KeyCode::Escape{return act::PAUSE;}if shell{return match k{KeyCode::ArrowUp|KeyCode::KeyW=>act::UP,KeyCode::ArrowDown|KeyCode::KeyS=>act::DOWN,KeyCode::ArrowLeft=>act::LEFT,KeyCode::ArrowRight=>act::RIGHT,KeyCode::Enter|KeyCode::Space=>act::CONFIRM,KeyCode::KeyQ=>act::PREV,KeyCode::KeyE=>act::NEXT,_=>0};}match k{KeyCode::KeyE=>act::INTERACT,KeyCode::KeyR=>act::RELOAD,KeyCode::KeyQ=>act::NEXT_GUN,KeyCode::KeyG=>act::THROW,KeyCode::KeyV=>act::MELEE,KeyCode::KeyM=>act::MAP,KeyCode::KeyH=>act::HEAL,KeyCode::KeyP=>act::PILL,KeyCode::KeyT=>act::TRACKER,KeyCode::KeyB=>act::MONOCULAR,KeyCode::KeyC=>act::CROUCH,KeyCode::KeyZ=>act::PRONE,KeyCode::Tab=>act::CARD,KeyCode::KeyF=>act::SEAT,_=>0}}
